using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Security.Cryptography;
namespace Musikbox {
 public sealed class FileTagAction {
  sealed class Entry {public string Before,After,OldCopy,NewCopy,OldHash,NewHash;public Dictionary<string,string> OldTags,NewTags;}
  readonly List<Entry> entries=new List<Entry>();public readonly string Id=Guid.NewGuid().ToString("N");bool applied,commitAttempted;
  static string Hash(string path){using(var file=File.OpenRead(path))using(var hash=SHA256.Create())return BitConverter.ToString(hash.ComputeHash(file));}
  public static FileTagAction Apply(IList<TagChange> changes,string backupRoot,Action check=null){TagConversion.Validate(changes);var action=new FileTagAction();try{foreach(var c in changes){if(check!=null)check();var existing=TagFields.Read(c.Source);var previous=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);foreach(var field in c.Fields)previous[field.Key]=existing.ContainsKey(field.Key)?existing[field.Key]:"";if(c.Fields.Count>0){TagFields.Write(c.Source,c.Fields);TagFields.Verify(c.Source,c.Fields);}if(c.ArtworkPath!=null)EmbeddedArtwork.Write(c.Source,c.ArtworkPath,c.AppendArtwork);if(!String.Equals(c.Source,c.Target,StringComparison.OrdinalIgnoreCase))File.Move(c.Source,c.Target);action.entries.Add(new Entry{Before=c.Source,After=c.Target,OldTags=previous,NewTags=new Dictionary<string,string>(c.Fields,StringComparer.OrdinalIgnoreCase)});}action.applied=true;foreach(var c in changes){c.Song.Source=c.Target;if(c.Song.PendingTags!=null)foreach(string key in c.Fields.Keys)c.Song.PendingTags.Remove(key);if(c.ArtworkPath!=null)c.Song.Artwork=null;var read=MediaMetadata.Read(c.Target);c.Song.Artist=read.Artist;c.Song.Title=read.Title;c.Song.Album=read.Album;if(c.Fields.ContainsKey("album"))c.Song.AlbumOverride=true;c.Song.Year=read.Year;c.Song.Genre=read.Genre;c.Song.Comment=read.Comment;c.Song.Track=read.Track;c.Song.AcoustidId=read.AcoustidId;c.Song.Bitrate=read.Bitrate;c.Song.TagType=read.TagType;c.Song.PreparedSource=c.Song.PreparedProfile=null;if(c.Song.PendingTags!=null)foreach(var pending in c.Song.PendingTags){switch(pending.Key){case "artist":c.Song.Artist=pending.Value;break;case "title":c.Song.Title=pending.Value;break;case "album":c.Song.Album=pending.Value;break;case "year":c.Song.Year=pending.Value;break;case "genre":c.Song.Genre=pending.Value;break;case "track":c.Song.Track=pending.Value;break;case "comment":c.Song.Comment=pending.Value;break;case "acoustid_id":c.Song.AcoustidId=pending.Value;break;}}}return action;}catch{throw;}}
  public void Restore(bool forward){foreach(var e in entries){string current=forward?e.Before:e.After,target=forward?e.After:e.Before;if(!File.Exists(current))throw new IOException("Datei nicht gefunden: "+current);if(!String.Equals(current,target,StringComparison.OrdinalIgnoreCase)&&File.Exists(target))throw new IOException("Ziel bereits vorhanden: "+target);}foreach(var e in entries){string current=forward?e.Before:e.After,target=forward?e.After:e.Before;if(!String.Equals(current,target,StringComparison.OrdinalIgnoreCase))File.Move(current,target);if(e.OldTags.Count>0)TagFields.Write(target,forward?e.NewTags:e.OldTags);}applied=forward;}
 }
